        new("لم يتمكن ويندوز من تحرير ذاكرة البرنامج المحدد، أو أن العملية انتهت قبل التنفيذ.", "لم يتمكن ويندوز من تحرير ذاكرة البرنامج المحدد، أو أن العملية انتهت قبل التنفيذ.", "Windows could not release memory for the selected application, or the process ended before the action ran."),
        new("البرنامج: {0}. المستخدم قبل: {1}، بعد: {2}، الانخفاض المقاس: {3}.", "البرنامج: {0}. المستخدم قبل: {1}، بعد: {2}، الانخفاض المقاس: {3}.", "Application: {0}. Used before: {1}; after: {2}; measured reduction: {3}."),
        new("تعذر إكمال التحرير المؤقت لذاكرة البرنامج.", "تعذر إكمال التحرير المؤقت لذاكرة البرنامج.", "Could not complete the temporary memory release for the application."),
        new("@MemoryReleaseResult", "اكتمل التحرير المؤقت للبرنامج «{0}».\n\nإجمالي الرام: {1}\nالمستخدم قبل: {2} ({3}%)\nالمتاح قبل: {4}\nالمستخدم بعد: {5} ({6}%)\nالمتاح بعد: {7}\nالانخفاض المقاس: {8}\n\nهذا لا يزيد سعة الرام، وقد يعيد ويندوز تحميل الصفحات عند استخدام البرنامج.", "Temporary memory release completed for “{0}”.\n\nTotal RAM: {1}\nUsed before: {2} ({3}%)\nAvailable before: {4}\nUsed after: {5} ({6}%)\nAvailable after: {7}\nMeasured reduction: {8}\n\nThis does not increase RAM capacity, and Windows may reload the pages when the application is used."),
