        new("@VirtualMemoryCustomStatus", "الإعداد الحالي مخصص: البداية {0} ميغابايت، والحد الأقصى {1} ميغابايت.", "The current setting is custom: {0} MB initial and {1} MB maximum."),
        new("@VirtualMemoryNotDetected", "لم يتم اكتشاف ملف ذاكرة افتراضية على قرص النظام.", "No virtual-memory file was detected on the system drive."),
